require_once __DIR__."/../config/app.php";require_login();require_post_csrf();$id=(int)($_POST["id"]??0);$st=$pdo->prepare("SELECT * FROM proposals WHERE id=?");$st->execute([$id]);$p=$st->fetch();if(!$p)redirect("index.php");if(!can_delete_proposal($p)){http_response_code(403);exit("Tidak memiliki hak untuk menghapus.");}if($p["proposal_file"]){$f=__DIR__."/../uploads/proposals/".basename($p["proposal_file"]);if(is_file($f))@unlink($f);}$pdo->prepare("DELETE FROM proposals WHERE id=?")->execute([$id]);flash("success","Proposal berhasil dihapus.");redirect("index.php");